"""Exact additive eight-job contract; old jobs keep every command and watchdog."""
BUILDING_BATCH_JOB = '  building-batch:\n    # Independent mandatory multi-planet application; never borrowed legacy evidence.\n    if: github.event_name != \'push\' || !contains(github.event.head_commit.message, \'[deep-source]\')\n    runs-on: ubuntu-latest\n    timeout-minutes: 15\n    outputs:\n      common-identity-sha256: ${{ steps.common_identity.outputs.common-sha256 }}\n      building-batch-fixture-sha256: ${{ steps.batch_census.outputs.building-batch-fixture-sha256 }}\n      building-batch-census-sha256: ${{ steps.batch_census.outputs.building-batch-census-sha256 }}\n    steps:\n      - uses: actions/checkout@v7\n        with:\n          ref: ${{ github.sha }}\n          fetch-depth: 0\n          persist-credentials: false\n      - uses: actions/setup-node@v7\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - run: npm run build\n      - name: Offline exact batch source, fixture, authority and mandatory gate contracts\n        run: |\n          python scripts/test_building_batch_provenance.py --verify-candidate "$GITHUB_SHA" -v\n          python -m unittest discover -s scripts -p \'test_building_batch_*.py\' -v\n      - name: Prepare independently clean exact batch execution source\n        run: |\n          test "$(git rev-parse HEAD)" = "$GITHUB_SHA"\n          test -z "$(git status --porcelain=v1 --untracked-files=all)"\n          git worktree add --detach "$RUNNER_TEMP/building-batch-current" "$GITHUB_SHA"\n          ln -s "$GITHUB_WORKSPACE/node_modules" "$RUNNER_TEMP/building-batch-current/node_modules"\n          test -z "$(git -C "$RUNNER_TEMP/building-batch-current" status --porcelain=v1 --untracked-files=all)"\n      - name: Bind exact batch source assets and actual Node runtime\n        id: common_identity\n        run: python scripts/parallel-gate-identity.py --source-root "$RUNNER_TEMP/building-batch-current"\n      - name: Generate fresh-start real-colonization source and independent finite-payment goldens\n        run: |\n          (cd "$RUNNER_TEMP/building-batch-current" && node --import tsx scripts/building-batch-natural-fixture.mjs --out "$GITHUB_WORKSPACE/building-batch-source-evidence/fixture") > building-batch-producer.log 2>&1\n          python scripts/check-building-batch-fixture.py --fixture building-batch-source-evidence/fixture/fixture.json --require-clean --check-current-source --mutation-self-test\n          sha256sum building-batch-source-evidence/fixture/fixture.json > building-batch-source-evidence/fixture.sha256.txt\n          test -z "$(git -C "$RUNNER_TEMP/building-batch-current" status --porcelain=v1 --untracked-files=all)"\n      - name: Browser prerequisites\n        timeout-minutes: 4\n        run: bash scripts/browser-prerequisites.sh\n      - name: Mandatory bounded real multi-planet confirmation and lifecycle acceptance\n        id: batch_census\n        shell: bash\n        run: |\n          npm run preview -- --host 127.0.0.1 --port 4173 > building-batch-preview.log 2>&1 &\n          SERVER_PID=$!\n          trap \'kill "$SERVER_PID" || true\' EXIT\n          READY=0\n          for i in $(seq 1 30); do\n            if curl -fsS http://127.0.0.1:4173/Infinity/release.json > /dev/null; then READY=1; break; fi\n            sleep 1\n          done\n          test "$READY" = 1\n          CHROME="$(command -v google-chrome || command -v google-chrome-stable)"\n          timeout --signal=TERM --kill-after=5s 660s xvfb-run -a python scripts/browser-building-batch.py --url http://127.0.0.1:4173/Infinity/ --fixture building-batch-source-evidence/fixture/fixture.json --expected-fixture-sha256 "$(sha256sum building-batch-source-evidence/fixture/fixture.json | cut -d\' \' -f1)" --expected-sha "$GITHUB_SHA" --expected-version 0.6.31-alpha.1 --runtime-node "$(node --version)" --common-identity common-identity.json --chromium "$CHROME" --output building-batch-evidence\n          python scripts/building_batch_census.py report --report building-batch-evidence/report.json --fixture building-batch-source-evidence/fixture/fixture.json --common-identity common-identity.json --expected-sha "$GITHUB_SHA" --output building-batch-census.json\n      - name: Archive exact readable batch source\n        if: always()\n        run: git archive --format=zip --prefix=Infinity/ HEAD > building-batch-source.zip\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: building-batch-${{ github.sha }}\n          path: |\n            dist\n            building-batch-source.zip\n            common-identity.json\n            building-batch-source-evidence\n            building-batch-evidence\n            building-batch-census.json\n            building-batch-producer.log\n            building-batch-preview.log\n          retention-days: 7\n          if-no-files-found: error\n'
AGGREGATE_ADDITION = '      - name: Download exact same-run building batch artifact\n        uses: actions/download-artifact@v4\n        with:\n          name: building-batch-${{ github.sha }}\n          path: ${{ runner.temp }}/building-batch-artifact\n      - name: Independently recompute complete batch scenario and raw evidence census\n        env:\n          JOB_RESULTS: ${{ toJSON(needs) }}\n        run: python scripts/building_batch_census.py aggregate --artifact "$RUNNER_TEMP/building-batch-artifact" --expected-sha "$GITHUB_SHA" --output building-batch-aggregate-census.json\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: building-batch-aggregate-census-${{ github.sha }}\n          path: building-batch-aggregate-census.json\n          retention-days: 7\n          if-no-files-found: error\n'
